{
  "title": "Tax filing workaround, product ideas and app design discussion",
  "topics": [
    {
      "id": "tax-filing-workaround",
      "title": "Tax filing workaround via aunt Sveta",
      "claims": [
        {
          "text": "Paying 500 UAH to aunt Sveta allowed correction of declaration errors and avoided larger penalties.",
          "evidence": [1]
        },
        {
          "text": "The inspector previously approved declarations without review for 1.5 years and was later reprimanded.",
          "evidence": [1]
        },
        {
          "text": "Re‑filing after the aunt's help cost about 1 000 UAH instead of the full fines.",
          "evidence": [1]
        },
        {
          "text": "Mistakes often stem from mixing up columns and subtraction signs rather than tax calculation formulas.",
          "evidence": [8]
        },
        {
          "text": "The calculator they use works only with a Ukrainian‑currency (UAH) FOP; other currencies require manual conversion based on the day‑of‑deposit rate.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase considerations",
      "claims": [
        {
          "text": "No domain has been bought yet.",
          "evidence": [2]
        },
        {
          "text": "Someone suggested buying a calculator first, then using the money for a domain.",
          "evidence": [4]
        },
        {
          "text": "One participant opposes buying a domain, calling it an unnecessary expense.",
          "evidence": [9]
        },
        {
          "text": "Another participant describes the domain as a “raw thing” that won’t evaporate even in heat.",
          "evidence": [10]
        }
      ]
    },
    {
      "id": "product-viability-web",
      "title": "Viability of a web‑based product",
      "claims": [
        {
          "text": "Web platforms are the simplest but significantly less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "SEO performance is poor; a site on the 10th Google page gets virtually no traffic.",
          "evidence": [11]
        },
        {
          "text": "There is no external traffic from Instagram/Threads and no contextual ads.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero because a paywall appears within the first 10 seconds, before the product can demonstrate value.",
          "evidence": [11]
        },
        {
          "text": "Conversion is assumed to be zero; the product does not simplify anything or integrate with banks or tax cabinets.",
          "evidence": [11]
        }
      ]
    },
    {
      "id": "cross-platform-development",
      "title": "Cross‑platform development approach",
      "claims": [
        {
          "text": "A fast delivery schedule (< 1 week from zero to release) is desirable.",
          "evidence": [12]
        },
        {
          "text": "Flutter was used as the cross‑platform stack in the referenced successful case.",
          "evidence": [12]
        }
      ]
    },
    {
      "id": "bundle-password-scam",
      "title": "Bundle with password stored in local storage and security concerns",
      "claims": [
        {
          "text": "The only password is stored in local storage as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "There is speculation that the password can be found by searching the source code.",
          "evidence": [21]
        },
        {
          "text": "Responses suggest the price of 299 UAH was not actually paid, implying the bundle may be a scam.",
          "evidence": [22, 24, 26, 32, 33, 34]
        },
        {
          "text": "The product is positioned as a “local‑first” app where USD/UAH rates refresh every 5 minutes and calculations happen instantly in the browser.",
          "evidence": [29]
        },
        {
          "text": "A “free vibe‑code” project description emphasizes that the bundle’s value is limited to the password stored locally.",
          "evidence": [30]
        }
      ]
    }
  ],
  "decisions": [
    {
      "text": "Adopt Flutter as the cross‑platform development stack to achieve sub‑week delivery.",
      "evidence": [12]
    },
    {
      "text": "Design the app as a local‑first web application with client‑side calculations and a USD/UAH exchange rate that updates every 5 minutes.",
      "evidence": [29]
    },
    {
      "text": "Choose not to purchase a domain at this stage, citing it as an unnecessary expense.",
      "evidence": [9]
    }
  ],
  "openQuestions": [
    {
      "text": "Is the source code publicly accessible enough to locate the stored password?",
      "evidence": [21]
    },
    {
      "text": "Is there a market of at least ten users willing to pay 299 UAH for the product?",
      "evidence": [20]
    }
  ]
}
